# derive demo line-gap mask and compare output set
R,C=len(I),len(I[0]); pred=set()
for r in range(R):
 p=[c for c,x in enumerate(I[r]) if x==5]
 for a,b in zip(p,p[1:]): pred.update((r,c) for c in range(a+1,b))
for c in range(C):
 p=[r for r in range(R) if I[r][c]==5]
 for a,b in zip(p,p[1:]): pred.update((r,c) for r in range(a+1,b))
changes=set(changes)
print('pred',len(pred),'changed',len(changes),'intersection',len(pred&changes),'false positive',sorted(pred-changes),'missed',sorted(changes-pred))
